import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';import {chromium} from 'playwright';import {extract} from '../../engine/extract.mjs';import {enrichForms} from '../../engine/form-validation.mjs';import {verificationScreenshot} from '../../engine/verify-screenshot.mjs';
const root=path.resolve('work/cf7-heldout'),records=JSON.parse(await readFile(path.join(root,'heldout-form-records.json'))),browser=await chromium.launch({channel:'chrome'}),results=[];
try{for(const record of records){const url=record.url;assert.equal(new URL(url).origin,'http://127.0.0.1:9438');const response=await fetch(url);assert.equal(response.status,200);const source=await response.text(),model=extract(source,url);await enrichForms({source:url,pages:[model]},{get:async url=>{assert.equal(new URL(url).origin,'http://127.0.0.1:9438');const response=await fetch(url);return {status:response.status,body:await response.text()};}});assert.equal(model.sourceForms.length,1);const contract=model.sourceForms[0];assert.equal(contract.provider,'contact-form-7');
 if(url.includes('studio-news')){assert.equal(contract.fields.find(f=>f.name==='full-name').minlength,'2');assert.equal(contract.fields.find(f=>f.name==='full-name').maxlength,'60');assert.ok(contract.fields.some(f=>f.name.startsWith('topics')));assert.equal(contract.fields.find(f=>f.name==='newsletter-policy').required,true);}
 else{assert.equal(contract.fields.find(f=>f.name==='brief').required,true);assert.equal(contract.fields.find(f=>f.name==='brief').maxFileBytes,131072);assert.equal(contract.fields.find(f=>f.name==='brief').accept,'.pdf,.txt');assert.equal(contract.fields.find(f=>f.name==='visitors').step,'2');assert.equal(contract.fields.filter(f=>f.requiredGroup==='weekdays[]').length,3);}
 const shots=[];for(const width of [1440,390]){const context=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await context.newPage();await page.route('**/*',route=>route.request().method()==='POST'?route.abort():route.continue());await page.goto(url,{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);const file=new URL(url).pathname.split('/').filter(Boolean)[0]+'-'+width+'.png';await verificationScreenshot(page,path.join(root,file),{fullPage:true});shots.push({width,file});await context.close();}
 results.push({route:new URL(url).pathname,definitionSHA256:createHash('sha256').update(record.definition).digest('hex'),fields:contract.fields,shots});}
 await writeFile(path.join(root,'heldout-source-check.json'),JSON.stringify({cases:results,sourceSubmissions:0},null,2));console.log(JSON.stringify({forms:results.length,screenshots:results.length*2,sourceSubmissions:0}));
}finally{await browser.close();}
